/* ---------------- strength standards ----------------
   Bodyweight multipliers for a 1RM across five tiers. These are the common
   able-bodied training tables: a reference point for motivation, not a verdict
   on anyone. Female thresholds come from a per-lift factor (index 5) rather
   than a second table — approximate, and honest about being so.
   Bodyweight movements (pull ups, dips, planks) are deliberately absent:
   ranking them needs bodyweight-plus-load handling this doesn't do yet. */
export const TIERS = ['Beginner', 'Novice', 'Intermediate', 'Advanced', 'Elite'];
const TIER_COLOR = ['var(--dim)', 'var(--blue)', 'var(--green)', 'var(--purple)', 'var(--gold)'];

