function stdFor(name) {
  const s = STD[name];
  if (!s) return null;
  const f = S.settings.sex === 'female' ? s[5] : 1;
  return s.slice(0, 5).map(v => v * f);
}

/* Score is 0–100 with each tier worth 20 points, so the bar moves smoothly
   between tiers instead of jumping. Uses best real e1RM — backfilled sets are
   already excluded by statsFor, so an estimate can't inflate a rank. */
export function rankFor(key) {
  /* Keyed on the leaf like everything else. It took a display name until 0.7.0,
     which silently returned no stats and emptied the rankings entirely.
     Strength standards are per movement, so stdFor still looks up by name. */
  const name = leafName(key);
  const bw = bodyweightKg();
  const st = statsFor(key);
  const th = stdFor(name);
  if (!bw || !st || !th) return null;

  const e1 = st.best.e1;
  const ratio = e1 / bw;
  const marks = th.map(m => m * bw);
  let score, tier, nextIdx = null;

  if (ratio < th[0]) {
    score = (ratio / th[0]) * 20;
    tier = -1;
    nextIdx = 0;
  } else {
    let i = 4;
    while (i > 0 && ratio < th[i]) i--;
    tier = i;
    if (i === 4) score = 100;
    else {
      score = 20 * (i + 1) + ((ratio - th[i]) / (th[i + 1] - th[i])) * 20;
      nextIdx = i + 1;
    }
  }

  return {
    name, key, leaf: keyLeaf(key), e1, ratio, score: clamp(score, 0, 100),
    tier, tierName: tier < 0 ? 'Untrained' : TIERS[tier],
    color: tier < 0 ? 'var(--dim)' : TIER_COLOR[tier],
    nextName: nextIdx == null ? null : TIERS[nextIdx],
    toNext: nextIdx == null ? 0 : marks[nextIdx] - e1,
    estOnly: st.estOnly, marks,
  };
}

export function allRanks() {
  return allStats().map(s => rankFor(s.key)).filter(Boolean)
    .sort((a, b) => b.score - a.score);
}

/* Each muscle's score is the share-weighted average of the ranks of every
   ranked lift that trains it. Only lifts with a standard contribute, so an
   untested muscle reads as absent rather than as zero. */
function muscleScores() {
  const acc = {};
  allRanks().forEach(r => {
    const m = exMuscles(r.name);
    if (!m) return;
    Object.entries(m).forEach(([k, share]) => {
      if (!MUSCLES[k]) return;
      acc[k] = acc[k] || { num: 0, den: 0, lifts: 0 };
      acc[k].num += r.score * share;
      acc[k].den += share;
      acc[k].lifts++;
    });
  });
  return Object.entries(acc)
    .map(([k, v]) => ({ key: k, name: MUSCLES[k], score: v.num / v.den, lifts: v.lifts }))
    .sort((a, b) => b.score - a.score);
}

/* ---------------- RECOVERY (D7) ----------------
   How much recent training is still in each muscle: working sets × effort by
   RIR × the movement's muscle share, decayed by the hours since. Derived at
   read time. r&d/specs/recovery-spec.md. */
export const RECOVERY = { tauBig: 36, tauSmall: 24, days: 7, fresh: 0.5, levels: [0.5, 1.25, 2.25, 3.25, 4.5] };   // ~effective hard sets still in the muscle
export const RECOVERY_WORDS = ['fresh', 'lightly worked', 'recovering', 'tired', 'fatigued', 'smashed'];
export const BIG_MUSCLES = ['quads', 'hams', 'glutes', 'erectors', 'lats', 'chest', 'upperback'];
export const muscleTau = k => BIG_MUSCLES.includes(k) ? RECOVERY.tauBig : RECOVERY.tauSmall;
export function setEffort(s) {
  if (isWarm(s)) return 0;
  let f = 0.8;
  if (s.rpe != null) { const rir = rpeToRir(s.rpe); f = rir <= 1 ? 1 : rir <= 2 ? 0.85 : rir <= 3 ? 0.7 : 0.55; }
  return isDrop(s) ? f * 0.6 : f;
}
export function woTime(wo) { return wo.end || wo.start || parseISO(wo.date).getTime() + 12 * 3600e3; }
export function fatigueMap(now = Date.now()) {
  const since = now - RECOVERY.days * 864e5, out = {};
  const list = S.workouts.filter(w => w.status === 'completed' && w.kind !== 'cardio' && woTime(w) >= since && woTime(w) <= now);
  if (S.active && S.active.kind !== 'cardio' && S.active.exercises) list.push({ ...S.active, end: now, live: true });
  list.forEach(wo => {
    const hrs = Math.max(0, (now - woTime(wo)) / 36e5);
    (wo.exercises || []).forEach(e => {
      const lm = e.leaf ? leafMuscles(e.leaf) : (exInfo(exName(e)) ? { m: exMuscles(exName(e)), tuned: exInfo(exName(e)).tuned } : null);
      const m = lm && lm.m;
      if (!m) return;
      const eff = e.sets.filter(s => (wo.live ? s.done : s.done !== false) && (s.r > 0 || s.sec > 0 || s.m > 0)).reduce((a, s) => a + setEffort(s), 0);
      if (!eff) return;
      const tuned = !!lm.tuned;
      Object.entries(m).forEach(([k, share]) => {
        if (!MUSCLES[k]) return;
        const f = eff * share * Math.exp(-hrs / muscleTau(k));
        const o = out[k] = out[k] || { key: k, name: MUSCLES[k], f: 0, derived: 0, from: [] };
        o.f += f; if (!tuned) o.derived += f;
        o.from.push({ name: exFull(e), date: wo.date, live: !!wo.live, f });
      });
    });
  });
  Object.values(out).forEach(o => {
    o.level = RECOVERY.levels.filter(x => o.f >= x).length;
    o.word = RECOVERY_WORDS[o.level];
    o.hours = o.f <= RECOVERY.fresh ? 0 : Math.ceil(muscleTau(o.key) * Math.log(o.f / RECOVERY.fresh));
    o.estimate = o.f > 0 && o.derived / o.f > 0.3;
    o.from.sort((a, b) => b.f - a.f);
  });
  return out;
}
/* ---------------- WEEKLY SETS PER MUSCLE (roadmap 01) ----------------
   Hard sets per muscle per Monday-week against MEV / MAV / MRV.
   r&d/specs/weekly-sets-spec.md. Derived at read time; only the lifter's
   target overrides are stored (settings.volTargets). */
const WEEKLY_SETS = { primaryOf: 0.8, secondary: 0.2, easyRir: 5, dropCredit: 0.5, weeks: 8 };
const VOL_TARGETS = {
  quads: [8, 14, 20], hams: [6, 12, 20], glutes: [4, 10, 16], erectors: [2, 6, 12],
  lats: [8, 14, 22], upperback: [8, 14, 22], traps: [4, 10, 20], chest: [8, 14, 22],
  fdelts: [0, 6, 12], sdelts: [8, 16, 26], triceps: [6, 12, 18], biceps: [8, 14, 22],
  forearms: [2, 8, 16], abs: [4, 10, 20], calves: [8, 12, 20],
};
export function volTarget(k) {
  const d = VOL_TARGETS[k] || [0, 10, 20], o = (S.settings.volTargets || {})[k];
  return o ? { mev: o.mev, mav: o.mav, mrv: o.mrv, custom: true } : { mev: d[0], mav: d[1], mrv: d[2], custom: false };
}
/* Whole-set credit per muscle from a lift's shares (spec §2). */
function setCredit(m) {
  const top = Math.max(...Object.values(m));
  const out = {};
  Object.entries(m).forEach(([k, s]) => {
    if (!MUSCLES[k]) return;
    const c = s >= top * WEEKLY_SETS.primaryOf ? 1 : s >= WEEKLY_SETS.secondary ? 0.5 : 0;
    if (c) out[k] = c;
  });
  return out;
}
/* A set's worth as a hard set: 1, ½ for a drop after the chain's first set, 0 if it doesn't count (spec §1). */
function hardSetWorth(s, i, live) {
  if (live ? !s.done : s.done === false) return 0;
  if (!(s.r > 0 || s.sec > 0 || s.m > 0) || isWarm(s)) return 0;
  if (s.rpe != null && rpeToRir(s.rpe) >= WEEKLY_SETS.easyRir) return 0;
  return isDrop(s) && i > 0 ? WEEKLY_SETS.dropCredit : 1;
}
function mondayOf(d) { const x = new Date(d.getFullYear(), d.getMonth(), d.getDate()); x.setDate(x.getDate() - (x.getDay() + 6) % 7); return x; }
/* Every counted set in [from, to) dates (ISO strings), one row each per muscle. */
export function hardSetRows(fromIso, toIso) {
  const list = S.workouts.filter(w => w.status === 'completed' && w.kind !== 'cardio' && w.kind !== 'mobility' && w.date >= fromIso && w.date < toIso)
    .map(w => ({ wo: w, live: false }));
  if (S.active && S.active.kind !== 'cardio' && S.active.kind !== 'mobility' && S.active.exercises) {
    const d = S.active.date || iso();
    if (d >= fromIso && d < toIso) list.push({ wo: S.active, live: true });
  }
  const rows = [];
  list.forEach(({ wo, live }) => (wo.exercises || []).forEach(e => {
    const lm = e.leaf ? leafMuscles(e.leaf) : (exInfo(exName(e)) ? { m: exMuscles(exName(e)) } : null);
    if (!lm || !lm.m) return;
    const cr = setCredit(lm.m);
    e.sets.forEach((s, i) => {
      const w = hardSetWorth(s, i, live);
      if (!w) return;
      Object.entries(cr).forEach(([k, c]) => rows.push({ k, n: w * c, credit: c, worth: w, name: exFull(e), date: live ? (wo.date || iso()) : wo.date, set: s, live }));
    });
  }));
  return rows;
}
/* { weeks: [mondayIso…] oldest first, by: { muscle: [count per week] } } */
export function weeklySets(nWeeks = WEEKLY_SETS.weeks) {
  const mon = mondayOf(new Date());
  const weeks = [];
  for (let i = nWeeks - 1; i >= 0; i--) { const d = new Date(mon); d.setDate(d.getDate() - 7 * i); weeks.push(iso(d)); }
  const end = new Date(mon); end.setDate(end.getDate() + 7);
  const by = {};
  hardSetRows(weeks[0], iso(end)).forEach(r => {
    let wi = weeks.length - 1; while (wi > 0 && r.date < weeks[wi]) wi--;
    (by[r.k] = by[r.k] || weeks.map(() => 0))[wi] += r.n;
  });
  return { weeks, by };
}
export function volStatus(n, t, partial) {
  if (n < t.mev) return { key: 'under', word: partial ? 'under so far' : 'under', color: 'var(--gold)' };
  if (n > t.mrv) return { key: 'over', word: 'over', color: 'var(--red)' };
  return { key: 'in', word: 'in range', color: 'var(--green)' };
}
export const setsTxt = n => nice(Math.round(n * 2) / 2);
function viewWeeklySets() {
  const { weeks, by } = weeklySets();
  const keys = Object.keys(MUSCLES).filter(k => (by[k] && by[k].some(v => v > 0)));
  if (!keys.length) return '';
  const cur = weeks.length - 1;
  const partial = new Date().getDay() !== 0;   // Sunday is the week's last day
  const rows = keys.map(k => {
    const t = volTarget(k), arr = by[k] || weeks.map(() => 0), n = arr[cur], st = volStatus(n, t, partial);
    const top = Math.max(t.mrv * 1.25, n, 1), pc = v => (clamp(v / top, 0, 1) * 100).toFixed(1);
    return `<div class="rank-row" data-volm="${k}" role="button" tabindex="0" aria-label="${esc(MUSCLES[k])}: ${setsTxt(n)} hard sets this week, ${st.word}. Range ${t.mev} to ${t.mrv}. Open the trend and targets">
      <div class="grow">
        <div class="n">${esc(MUSCLES[k])} <span class="sub" style="font-weight:400;font-size:11px">· ${st.word}</span></div>
        <div class="m">last week ${setsTxt(arr[cur - 1] || 0)} · range ${t.mev}–${t.mrv}${t.custom ? ' (yours)' : ''} ${why('vol', k)}</div>
        <div class="volbar" aria-hidden="true"><b style="left:${pc(t.mev)}%;width:${(pc(t.mrv) - pc(t.mev)).toFixed(1)}%"></b><u style="left:${pc(t.mav)}%"></u><i style="width:${pc(n)}%;background:${st.color}"></i></div>
      </div>
      <div class="rank-sc" style="color:${st.color}">${setsTxt(n)}</div>
    </div>`;
  }).join('');
  return `
  <div class="card flush" style="margin-bottom:13px">
    <div class="row between" style="padding:11px 13px 8px">
      <div class="eyebrow">Weekly sets · per muscle</div>
      <div class="sub" style="font-size:11px">week of ${fmtDate(weeks[cur], { day: 'numeric', month: 'short' })}</div>
    </div>
    ${rows}
    <div class="sub" style="padding:9px 13px 11px;border-top:1px solid var(--line)">
      Hard sets this week (Mon–Sun): warm-ups and sets at RIR 5+ left out, a lift's main muscle gets a whole set and its helpers half. Shaded band is MEV–MRV, the tick is MAV. Tap a muscle for its trend and to set your own range.
    </div>
  </div>`;
}
function volChart(weeks, arr, t) {
  const W = 320, H = 150, padL = 26, padR = 6, padT = 10, padB = 20;
  const top = Math.max(t.mrv * 1.15, ...arr, 1);
  const y = v => padT + (1 - v / top) * (H - padT - padB);
  const bw = (W - padL - padR) / weeks.length;
  const ticks = [0, t.mev, t.mav, t.mrv].filter((v, i, a) => a.indexOf(v) === i);
  return `<div class="chartbox"><svg class="chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" style="height:${H}px" role="img" aria-label="Hard sets per week for the last ${weeks.length} weeks: ${arr.map(setsTxt).join(', ')}">
    <rect x="${padL}" width="${W - padL - padR}" y="${y(t.mrv).toFixed(1)}" height="${(y(t.mev) - y(t.mrv)).toFixed(1)}" fill="var(--green)" opacity=".13"/>
    <line class="grid" x1="${padL}" x2="${W - padR}" y1="${y(t.mav).toFixed(1)}" y2="${y(t.mav).toFixed(1)}" style="stroke:var(--green)" stroke-dasharray="3 3"/>
    ${ticks.map(v => `<text class="axis" x="${padL - 4}" y="${(y(v) + 3).toFixed(1)}" text-anchor="end">${v}</text>`).join('')}
    ${arr.map((v, i) => { const st = volStatus(v, t, false), x0 = padL + i * bw + bw * 0.18;
      return `<rect x="${x0.toFixed(1)}" width="${(bw * 0.64).toFixed(1)}" y="${y(v).toFixed(1)}" height="${(y(0) - y(v)).toFixed(1)}" rx="2" style="fill:${i === arr.length - 1 ? 'var(--accent)' : st.color}" opacity="${i === arr.length - 1 ? 1 : 0.75}"/>`; }).join('')}
    ${[0, weeks.length - 1].map(i => `<text class="axis" x="${(padL + (i + 0.5) * bw).toFixed(1)}" y="${H - 5}" text-anchor="middle">${i === weeks.length - 1 ? 'this wk' : fmtDate(weeks[i], { day: 'numeric', month: 'short' })}</text>`).join('')}
  </svg></div>`;
}
export function openVolMuscle(k) {
  const { weeks, by } = weeklySets();
  const arr = by[k] || weeks.map(() => 0), t = volTarget(k), d = VOL_TARGETS[k] || [0, 10, 20];
  const rows = hardSetRows(weeks[weeks.length - 1], '9999').filter(r => r.k === k);
  const byLift = {};
  rows.forEach(r => { byLift[r.name] = (byLift[r.name] || 0) + r.n; });
  const lifts = Object.entries(byLift).sort((a, b) => b[1] - a[1]);
  const inp = (id, label, v) => `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="number" inputmode="decimal" step="1" min="0" value="${v}"></div>`;
  modal({
    title: `${MUSCLES[k]} · weekly sets`,
    body: `${volChart(weeks, arr, t)}
      <div class="sub" style="margin:6px 0 12px">Last ${weeks.length} weeks, Monday to Sunday. Band = your range, dashed line = MAV.</div>
      <div class="eyebrow" style="margin-bottom:6px">This week</div>
      ${lifts.length ? lifts.map(([n, v]) => `<div class="row between" style="padding:3px 0"><span>${esc(n)}</span><span class="mono">${setsTxt(v)}</span></div>`).join('')
        : '<div class="sub">Nothing for this muscle yet this week.</div>'}
      <div class="eyebrow" style="margin:14px 0 6px">Your range (hard sets a week)</div>
      <div class="grid3">${inp('vtMev', 'MEV · least', t.mev)}${inp('vtMav', 'MAV · aim', t.mav)}${inp('vtMrv', 'MRV · most', t.mrv)}</div>
      <div class="sub" style="margin-top:6px">Default ${d[0]} / ${d[1]} / ${d[2]} — rough general figures, a starting point. Your own recovery, age and training history move them.</div>`,
    foot: `${t.custom ? '<button class="btn ghost" id="vtReset">Reset</button>' : ''}<button class="btn ghost" data-close>Close</button><button class="btn primary" id="vtSave">Save range</button>`,
    onOpen: bg => {
      $('#vtSave', bg).onclick = () => {
        const v = ['#vtMev', '#vtMav', '#vtMrv'].map(s => Math.round(parseFloat($(s, bg).value)));
        if (v.some(x => !(x >= 0) || x > 60)) return toast('Each number should be 0–60');
        if (!(v[0] <= v[1] && v[1] <= v[2])) return toast('Keep MEV ≤ MAV ≤ MRV');
        S.settings.volTargets = { ...(S.settings.volTargets || {}) };
        if (v[0] === d[0] && v[1] === d[1] && v[2] === d[2]) delete S.settings.volTargets[k];
        else S.settings.volTargets[k] = { mev: v[0], mav: v[1], mrv: v[2] };
        save(); closeModal(); render(); toast(`${MUSCLES[k]} range saved`, 'green');
      };
      const rs = $('#vtReset', bg);
      if (rs) rs.onclick = () => { S.settings.volTargets = { ...(S.settings.volTargets || {}) }; delete S.settings.volTargets[k]; save(); closeModal(); render(); toast(`${MUSCLES[k]} back to the default range`); };
    },
  });
}

function trainedRecently() {
  const since = Date.now() - RECOVERY.days * 864e5;
  return S.workouts.some(w => w.status === 'completed' && w.kind !== 'cardio' && woTime(w) >= since) || !!(S.active && S.active.kind !== 'cardio');
}
function mapMode() {
  const m = S.settings.mapMode;
  if (m === 'strength' || m === 'recovery') return m;
  return trainedRecently() ? 'recovery' : 'strength';
}
function recoveryTap(o) {
  if (!o || !o.level) return 'fresh';
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const from = [...new Set(o.from.map(x => `${x.name} (${x.live ? 'today' : days[parseISO(x.date).getDay()]})`))].slice(0, 3).join(', ');
  return `${o.word} · fresh in ~${o.hours} h — ${from}${o.estimate ? ' · estimate — muscle split not checked' : ''}`;
}
/* Picker: the most-worked primary muscle of a leaf. */
export function leafFatigue(leaf, fm) {
  const lm = leafMuscles(leaf), m = lm && lm.m;
  if (!m) return null;
  const prim = Object.entries(m).sort((a, b) => b[1] - a[1]).filter(([, sh], i) => i === 0 || sh >= 0.25).map(([k]) => k);
  return prim.map(k => fm[k]).filter(Boolean).sort((a, b) => b.level - a.level)[0] || null;
}
export function fatigueDot(o) {
  if (!o) return '';
  const c = o.level >= 3 ? 'var(--red)' : o.level >= 1 ? 'var(--gold)' : 'var(--green)';
  return `<span class="fdot" style="background:${c}" role="img" aria-label="${esc(o.name)} ${esc(o.word)}" title="${esc(o.name)}: ${esc(o.word)}"></span>`;
}
export function fatigueSummary(fm) {
  const by = lv => Object.values(fm).filter(lv).sort((a, b) => b.f - a.f).map(o => o.name);
  const hot = by(o => o.level >= 3), mid = by(o => o.level >= 1 && o.level < 3);
  if (!hot.length && !mid.length) return '';
  return [hot.length ? `Still tired: ${hot.join(', ')}` : '', mid.length ? `Recovering: ${mid.join(', ')}` : ''].filter(Boolean).join(' · ');
}

/* ---------------- muscle map (skins) ----------------
   The body is painted from a skin sheet: one PNG holding every muscle at every
   tier, pre-positioned on the body, so drawing a region is just copying its
   cell onto the canvas. Any art works — the default heatmap colours, a goblin
   that turns into an orc, whatever. Authoring guide, template and generator:
   r&d/skins/README.md.

   Sheet layout (must match r&d/tools/skin-geometry.mjs):
     columns = layers in SKIN_LAYOUT[view] order (also the paint order)
     rows    = SKIN_TIERS; the front block's 6 rows, then the back block's 6
   Cell size is read from the image (width / 11, height / 12), so a sheet can
   be painted at any resolution as long as the grid is kept. `base` is the body
   itself and follows the lifter's overall tier. */
const SKIN_TIERS = ['none', ...TIERS];
const SKIN_LAYOUT = {
  front: ['base', 'traps', 'abs', 'quads', 'calves', 'chest', 'fdelts', 'sdelts', 'biceps', 'forearms'],
  back:  ['base', 'traps', 'upperback', 'lats', 'erectors', 'glutes', 'hams', 'calves', 'sdelts', 'triceps', 'forearms'],
};
const SKIN_COLS = 11, SKIN_ROWS = 12;
/* Only the placeholder ships for now: one colour per tier, darker as the rank
   rises. Proper art replaces or joins it later — add an entry here, the PNG
   to /skins/ and the path to ASSETS in sw.js.
   legend: tier colours for the swatch row under the map, when the skin is
   flat colour and a legend means something. */
const SKIN_TEMPLATE_COLORS = ['#ffc9b8', '#ff9a7a', '#ff5c35', '#c43a15', '#7a1f08'];   // = SHADES in r&d/tools/skin-sheet.mjs
const BODY_SKINS = [
  { id: 'template', name: 'Template', src: 'skins/template.png', legend: SKIN_TEMPLATE_COLORS },
  /* A figure skin (00-D2): one picture per tier, cut to the template's muscle
     shapes by r&d/tools/build-skin.cjs. Not precached — it is fetched the
     first time it's picked and kept from then on; offline before that, the
     map falls back to the template. */
  { id: 'goblin', name: 'Goblin to orc', src: 'skins/goblin.webp' },
];
const BODY_SKIN_KEY = 'ironlog-bodyskin-custom';   // imported sheet, as a data URL
/* Falls back to the first skin, so a removed skin id in old settings can't
   leave the map blank. */
const bodySkinId = () => {
  const id = S.settings.bodySkin;
  return id === 'custom' || BODY_SKINS.some(s => s.id === id) ? id : BODY_SKINS[0].id;
};

const _skinImg = {};   // id -> Promise<HTMLImageElement>
export function loadImage(src) {
  return new Promise((res, rej) => {
    const im = new Image();
    im.onload = () => res(im);
    im.onerror = () => rej(new Error('skin image failed to load'));
    im.src = src;
  });
}
function skinImage(id) {
  if (!_skinImg[id]) {
    const def = BODY_SKINS.find(s => s.id === id);
    _skinImg[id] = (def ? loadImage(def.src)
      : storeGet(BODY_SKIN_KEY).then(url => url ? loadImage(url) : Promise.reject(new Error('no custom skin'))))
      .catch(e => { delete _skinImg[id]; throw e; });
  }
  return _skinImg[id];
}

/* A sheet is usable when its grid gives cells at 1:2. Anything else is almost
   certainly not a skin (a photo, a cropped export). */
function skinSheetOk(im) {
  const cw = im.naturalWidth / SKIN_COLS, ch = im.naturalHeight / SKIN_ROWS;
  return cw >= 60 && Math.abs(ch / cw - 2) < 0.05;
}

function skinTierOf(score) {
  return score == null ? 'none' : SKIN_TIERS[1 + clamp(Math.floor(score / 20), 0, 4)];
}

/* Which cell to use for each layer of a view, and at what opacity. */
function skinPlan(view, scores, base) {
  const vals = Object.values(scores);
  const overall = base !== undefined ? base : vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
  return SKIN_LAYOUT[view].map((layer, col) => {
    const sc = layer === 'base' ? overall : (scores[layer] != null ? scores[layer] : null);
    const tier = skinTierOf(sc);
    const row = (view === 'back' ? SKIN_TIERS.length : 0) + SKIN_TIERS.indexOf(tier);
    return { layer, col, row };
  });
}

function paintBody(canvas, im, plan) {
  const cw = im.naturalWidth / SKIN_COLS, ch = im.naturalHeight / SKIN_ROWS;
  canvas.width = Math.round(cw); canvas.height = Math.round(ch);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  plan.forEach(p => ctx.drawImage(im, p.col * cw, p.row * ch, cw, ch, 0, 0, canvas.width, canvas.height));
}

/* Topmost muscle with paint under the tap, read from the sheet itself —
   so hit areas always match the art, whatever shape a skin gives a muscle. */
const _probe = document.createElement('canvas');
_probe.width = _probe.height = 1;
function muscleAt(im, plan, fx, fy) {
  const cw = im.naturalWidth / SKIN_COLS, ch = im.naturalHeight / SKIN_ROWS;
  const ctx = _probe.getContext('2d', { willReadFrequently: true });
  for (let i = plan.length - 1; i >= 0; i--) {
    const p = plan[i];
    if (p.layer === 'base') continue;
    ctx.clearRect(0, 0, 1, 1);
    ctx.drawImage(im, p.col * cw + fx * cw, p.row * ch + fy * ch, 1, 1, 0, 0, 1, 1);
    if (ctx.getImageData(0, 0, 1, 1).data[3] > 40) return p.layer;
  }
  return null;
}

function viewMuscleMap() {
  const ms = muscleScores();
  if (!ms.length && !trainedRecently()) return '';
  const def = BODY_SKINS.find(s => s.id === bodySkinId());
  const skinName = def ? def.name : 'Custom';
  const mode = ms.length ? mapMode() : 'recovery';
  const fm = mode === 'recovery' ? fatigueMap() : null;
  const est = fm ? Object.values(fm).filter(o => o.level && o.estimate).length : 0;
  return `
  <div class="card" style="margin-bottom:13px">
    <div class="row" style="justify-content:space-between;align-items:center;margin-bottom:10px">
      <div class="eyebrow">Muscle map</div>
      <button class="chip" id="bodySkinBtn" style="cursor:pointer">Skin: ${esc(skinName)} ▾</button>
    </div>
    ${ms.length ? `<div class="seg" id="mapMode" style="margin-bottom:10px">
      <button data-mm="strength" class="${mode === 'strength' ? 'on' : ''}">Strength</button><button data-mm="recovery" class="${mode === 'recovery' ? 'on' : ''}">Recovery</button></div>` : ''}
    ${fm ? `<div class="sub" style="margin-bottom:8px">${esc(fatigueSummary(fm) || 'Everything fresh — nothing trained hard in the last few days.')}</div>` : ''}
    <div class="row" style="gap:14px;align-items:flex-start">
      <div class="grow" style="text-align:center">
        <canvas data-bodyview="front" style="width:100%;height:auto;aspect-ratio:1/2;display:block;cursor:pointer"></canvas>
        <div class="sub" style="margin-top:4px">Front</div>
      </div>
      <div class="grow" style="text-align:center">
        <canvas data-bodyview="back" style="width:100%;height:auto;aspect-ratio:1/2;display:block;cursor:pointer"></canvas>
        <div class="sub" style="margin-top:4px">Back</div>
      </div>
    </div>
    ${def && def.legend && mode === 'recovery' ? `<div class="row" style="gap:5px;margin-top:12px;flex-wrap:wrap">
      <span class="row" style="gap:4px;align-items:center;font-size:10.5px;color:var(--dim)">
        <i style="width:9px;height:9px;border-radius:2px;background:#4a5263;display:inline-block"></i>Fresh</span>
      ${['Light', 'Recovering', 'Tired', 'Fatigued', 'Smashed'].map((t, i) => `<span class="row" style="gap:4px;align-items:center;font-size:10.5px;color:var(--dim)">
        <i style="width:9px;height:9px;border-radius:2px;background:${def.legend[i]};display:inline-block"></i>${t}</span>`).join('')}
    </div>` : ''}
    ${def && def.legend && mode !== 'recovery' ? `<div class="row" style="gap:5px;margin-top:12px;flex-wrap:wrap">
      ${TIERS.map((t, i) => `<span class="row" style="gap:4px;align-items:center;font-size:10.5px;color:var(--dim)">
        <i style="width:9px;height:9px;border-radius:2px;background:${def.legend[i]};display:inline-block"></i>${t}</span>`).join('')}
      <span class="row" style="gap:4px;align-items:center;font-size:10.5px;color:var(--dim)">
        <i style="width:9px;height:9px;border-radius:2px;background:#4a5263;display:inline-block"></i>Not ranked</span>
    </div>` : ''}
    <div class="sub" style="margin-top:8px">${mode === 'recovery'
      ? `Tap a muscle for what's in it and when it's fresh. Last 7 days, weighted by RIR — a guide, not a measurement${est ? `; ${est} muscle${est === 1 ? '' : 's'} lean on estimated lift splits` : ''}.`
      : 'Tap a muscle for its score.'}</div>
  </div>`;
}

/* Called after the analytics page renders. */
export function wireMuscleMap(v) {
  const canvases = [...v.querySelectorAll('canvas[data-bodyview]')];
  const btn = $('#bodySkinBtn', v);
  if (btn) btn.onclick = openBodySkins;
  v.querySelectorAll('[data-mm]').forEach(b => b.onclick = () => { S.settings.mapMode = b.dataset.mm; save(); render(); });
  if (!canvases.length) return;
  const scores = {};
  const ms0 = muscleScores();
  ms0.forEach(m => { scores[m.key] = m.score; });
  const mode = ms0.length ? mapMode() : 'recovery';
  const fm = mode === 'recovery' ? fatigueMap() : null;
  const vals = Object.values(scores);
  const strengthBase = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
  // recovery reuses the tier rows as intensity: level 1..5 -> tier 1..5, fresh -> none
  const paintScores = fm ? Object.fromEntries(Object.values(fm).filter(o => o.level > 0).map(o => [o.key, (o.level - 1) * 20 + 10])) : scores;
  const id = bodySkinId();
  skinImage(id).then(im => {
    canvases.forEach(cv => {
      const plan = skinPlan(cv.dataset.bodyview, paintScores, fm ? strengthBase : undefined);
      paintBody(cv, im, plan);
      cv.onclick = e => {
        const r = cv.getBoundingClientRect();
        const key = muscleAt(im, plan, (e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height);
        if (!key) return;
        if (fm && debugOn()) return openWhy('rec', [key]);
        if (fm) return toast(`${MUSCLES[key]} · ${recoveryTap(fm[key])}`);
        const m = muscleScores().find(x => x.key === key);
        if (!m) return toast(`${MUSCLES[key]} — no ranked lift trains it yet`);
        const i = clamp(Math.floor(m.score / 20), 0, 4);
        toast(`${m.name} · ${Math.round(m.score)} · ${TIERS[i]} — from ${m.lifts} ranked lift${m.lifts === 1 ? '' : 's'}`);
      };
    });
  }).catch(() => {
    /* A missing custom sheet (cleared storage) falls back rather than
       leaving an empty card. */
    if (id !== BODY_SKINS[0].id) { S.settings.bodySkin = BODY_SKINS[0].id; save(); render(); }
  });
}

function openBodySkins() {
  const cur = bodySkinId();
  modal({
    title: 'Muscle map skin',
    body: `
      <div class="sub" style="margin-bottom:10px">A skin is one image holding every muscle at every tier. Paint your own on the paint guide and import it.</div>
      <div id="bsList">
        ${[...BODY_SKINS, { id: 'custom', name: 'Custom (imported)' }].map(s => `
          <button class="btn ${s.id === cur ? '' : 'ghost'}" data-bs="${s.id}" style="width:100%;margin-bottom:7px;justify-content:flex-start">
            ${s.id === cur ? '✓ ' : ''}${esc(s.name)}</button>`).join('')}
      </div>
      <div class="hr"></div>
      <button class="btn ghost" id="bsImport" style="width:100%;margin-bottom:7px">Import a skin sheet (PNG)…</button>
      <a class="btn ghost" href="r%26d/skins/paint-guide.png" download="ironlog-skin-paint-guide.png" style="width:100%;text-align:center;display:block;text-decoration:none">Download the paint guide</a>
      <input type="file" id="bsFile" accept="image/png,image/webp" style="display:none">`,
    onOpen: bg => {
      const pick = id => {
        S.settings.bodySkin = id; save(); closeModal(); render();
      };
      bg.querySelectorAll('[data-bs]').forEach(b => b.onclick = () => {
        const id = b.dataset.bs;
        if (id !== 'custom') return pick(id);
        storeGet(BODY_SKIN_KEY).then(u => u ? pick('custom') : $('#bsFile', bg).click());
      });
      $('#bsImport', bg).onclick = () => $('#bsFile', bg).click();
      $('#bsFile', bg).onchange = e => {
        const f = e.target.files[0];
        if (!f) return;
        const rd = new FileReader();
        rd.onload = async () => {
          try {
            const im = await loadImage(rd.result);
            if (!skinSheetOk(im)) return toast(`That image isn't a skin sheet — it needs the paint guide's 11 × 12 grid of 1:2 cells.`);
            if (!(await storePut(BODY_SKIN_KEY, rd.result))) return toast('Could not save the skin on this device');
            delete _skinImg.custom;
            pick('custom');
            toast('Skin imported');
          } catch (err) { toast('Could not read that image'); }
        };
        rd.readAsDataURL(f);
      };
    },
  });
}

/* ---------------- PR engine ---------------- */
// Returns every logged (completed, non-warmup) set for an exercise, oldest first.
// `before` (ISO date, or a session — see isBefore) limits it to "history as it stood".
// A set is a set when it has reps; weight may be 0 (pull ups, dips, planks).
export function historyFor(key, before) {
  const out = [];
  S.workouts.filter(wo => wo.status === 'completed' && isBefore(wo, before)).forEach(wo => {
    // weight × reps only: capped sets, carries and races keep their own records
    wo.exercises.filter(e => exKey(e) === key && inRepsPool(e)).forEach(e => {
      e.sets.filter(s => s.done && isPRSet(s) && s.r > 0).forEach(s => {
        out.push({ date: wo.date, w: s.w, r: s.r, rpe: s.rpe, e1: e1rm(s.w, s.r, s.rpe), workoutId: wo.id, est: wo.source === 'backfill' });
      });
    });
  });
  return out.sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : 0);
}

export function statsFor(key, before) {
  const h = historyFor(key, before);
  if (!h.length) return null;
  const sessions = [...new Set(h.map(s => s.date))].sort();
  /* Backfilled sets are the plan's prescription, not what came off the bar.
     They count toward volume and consistency but must not set a PR. */
  const real = h.filter(s => !s.est);
  /* Counting backfilled sets is the default: for anyone who entered their
     real training history that way, excluding them throws the history out
     the moment one live set lands. Turn it off in Settings if the backfill
     really was just the plan's prescription. */
  const countEst = S.settings.prCountEst !== false;
  const prSrc = countEst ? h : (real.length ? real : h);
  let best = prSrc[0], bestW = prSrc[0], bestBw = null;
  const byRep = {};                    // reps -> heaviest weight
  let volume = 0;
  prSrc.forEach(s => {
    if (s.e1 > best.e1) best = s;
    if (s.w > bestW.w || (s.w === bestW.w && s.r > bestW.r)) bestW = s;
    if (!byRep[s.r] || s.w > byRep[s.r].w) byRep[s.r] = s;
    if (!(s.w > 0) && (!bestBw || s.r > bestBw.r)) bestBw = s;   // bodyweight rep record
  });
  h.forEach(s => { volume += s.w * s.r; });
  // per-session best e1RM series
  const series = sessions.map(d => {
    const ss = h.filter(s => s.date === d);
    return {
      date: d,
      e1: Math.max(...ss.map(s => s.e1)),
      top: Math.max(...ss.map(s => s.w)),
      vol: ss.reduce((a, s) => a + s.w * s.r, 0),
      sets: ss.length,
    };
  });
  const first = series[0], last = series[series.length - 1];
  const delta = last.e1 - first.e1;
  const pct = first.e1 ? (delta / first.e1) * 100 : 0;
  return {
    key, name: leafName(key), leaf: keyLeaf(key),
    sessions: sessions.length, totalSets: h.length, volume,
    best, bestW, bestBw, byRep, series, first, last, delta, pct,
    bestIsEst: !!best.est, bestWIsEst: !!bestW.est,
    estOnly: !real.length,
    lastDate: sessions[sessions.length - 1], firstDate: sessions[0],
  };
}

// map of exercise -> stats, cached per render pass
let _statCache = null;
export function allStats() {
  if (_statCache) return _statCache;
  const names = new Set();
  S.workouts.filter(w => w.status === 'completed').forEach(wo => wo.exercises.forEach(e => names.add(exKey(e))));
  _statCache = [...names].filter(Boolean).map(k => statsFor(k)).filter(Boolean)
    .sort((a, b) => b.sessions - a.sessions || a.name.localeCompare(b.name));
  return _statCache;
}
export function bust() { _statCache = null; _prCache = null; }

function prFor(name) { return statsFor(name); }

/* One rule for "does this set beat the history?" — shared by the live tick,
   voice logging, finishWorkout and the derived PR list below, so they can't
   drift. `st` is statsFor() output for the history being beaten; null means
   nothing logged yet, which is "first time", not a PR. RPE counts on both
   sides of the comparison: history's e1 already includes it. */
export function beatsBest(st, w, r, rpe) {
  if (!st) return false;
  /* Bodyweight (w = 0): e1RM is meaningless, so the record is reps. Compared
     only against earlier bodyweight sets of the same movement — a weighted
     history is never "beaten" by an unloaded set. */
  if (!(w > 0)) return !!st.bestBw && r > st.bestBw.r;
  return e1rm(w, r, rpe) > st.best.e1;
}

/* The session's best set of an exercise: heaviest e1RM if anything was
   loaded, otherwise most reps. */
export function bestSetOf(sets) {
  const loaded = sets.filter(s => s.w > 0);
  if (loaded.length) return loaded.reduce((a, b) => e1rm(b.w, b.r, b.rpe) > e1rm(a.w, a.r, a.rpe) ? b : a);
  return sets.reduce((a, b) => b.r > a.r ? b : a);
}

/* PRs derived at read time from the history dated before the session, so
   imports, backfills, deletions and edits are all reflected. summary.prs is
   still written at finish (the summary modal shows it, "first time" and all)
   but nothing else treats it as truth. One entry per exercise: its best set. */
let _prCache = null;
export function prsFor(wo) {
  if (!_prCache) _prCache = new Map();
  if (_prCache.has(wo.id)) return _prCache.get(wo.id);
  const out = [];
  wo.exercises.forEach(e => {
    out.push(...shapePRs(e, wo, wo.id));   // holds, carries, races, caps, series
    if (!inRepsPool(e)) return;
    const sets = e.sets.filter(s => s.done && isPRSet(s) && s.r > 0);
    if (!sets.length) return;
    const st = statsFor(exKey(e), wo);   // earlier days, and earlier the same day (3.6)
    if (!st) return;
    const best = bestSetOf(sets);
    if (beatsBest(st, best.w, best.r, best.rpe)) {
      out.push({ name: exName(e), key: exKey(e), w: best.w, r: best.r, e1: e1rm(best.w, best.r, best.rpe), prev: st.best.e1,
                 prevReps: st.bestBw ? st.bestBw.r : 0 });
    }
  });
  _prCache.set(wo.id, out);
  return out;
}

// Best single. An actual 1-rep set always wins — that's the real PR. If you've
// never pulled a true single we fall back to the best estimate and flag it.
// `e1` carries the best estimate alongside, so a big rep PR still shows up.
export function bestSingleInfo(key) {
  const st = statsFor(key);
  if (!st) return { kg: 0, est: false, e1: 0 };
  const single = st.byRep[1];
  return single
    ? { kg: single.w, est: false, e1: st.best.e1 }
    : { kg: st.best.e1, est: true, e1: st.best.e1 };
}
function bestSingleKg(key) { return bestSingleInfo(key).kg; }

/* ---------------- plausibility ----------------
   Catches the fat-finger set — 2250 for 225, 80 reps for 8, a lb figure typed
   into a kg field — before it lands as a PR and skews every comparison after
   it. Every rule is a "does this look right?" prompt, never a block: a real
   300 kg pull must still be loggable. `before` reads history as it stood
   before a date, so editing an old session compares against what was true
   then rather than against itself. */
const PLAUS = {
  maxReps: 60,        // one set; past this it's a typo or a timed hold in the wrong field
  maxKg: 500,         // beyond the heaviest competition lifts
  overBest: 1.5,      // heavier than 1.5× your heaviest ever set of this movement
  overE1: 1.4,        // e1RM 40% past your best
  overElite: 1.5,     // no history: 1.5× the elite standard for your bodyweight
};

export function plausibility(key, w, r, rpe, before) {
  const name = leafName(key);
  const why = [];
  if (r > PLAUS.maxReps) why.push(`${r} reps in one set`);
  if (w > PLAUS.maxKg) why.push(`${wt(w)} is beyond any recorded lift`);
  if (rpe != null && (rpe < 1 || rpe > 10)) why.push(`${rpeToRir(rpe)} RIR — that's outside the usual 0 to 9 range`);
  const st = statsFor(key, before);
  const loaded = st && st.bestW.w > 0;
  if (loaded && w > 0) {
    const best = st.bestW.w;
    const lbAsKg = w / 2.2046226218;
    if (U() === 'kg' && w > best * 1.3 && lbAsKg >= best * 0.5 && lbAsKg <= best * 1.15) {
      why.push(`${wt(w)} looks like a lb figure — your heaviest ${name} is ${wt(best)}`);
    } else if (w > best * PLAUS.overBest) {
      why.push(`${wt(w)} is ${Math.round((w / best - 1) * 100)}% over your heaviest ${name} (${wt(best)})`);
    } else if (r > 0 && e1rm(w, r, rpe) > st.best.e1 * PLAUS.overE1) {
      const e1 = e1rm(w, r, rpe);
      why.push(`e1RM ${wt(e1)} is ${Math.round((e1 / st.best.e1 - 1) * 100)}% over your best (${wt(st.best.e1)})`);
    }
  } else if (w > 0) {
    const th = stdFor(name), bw = bodyweightKg();
    if (th && bw && w > th[4] * bw * PLAUS.overElite) {
      why.push(`${wt(w)} is ${(w / bw).toFixed(1)}× bodyweight — past the elite standard for ${name}, with nothing logged yet`);
    }
  }
  return why;
}

function plausLine(key, s) {
  const name = leafName(key);
  return `${name} · ${s.w > 0 ? wt(s.w) + ' × ' : ''}${s.r} reps${s.rpe != null ? ' @ ' + rpeToRir(s.rpe) + ' RIR' : ''}`;
}

/* One set, one prompt. `ok` runs only on "Log anyway". */
export function plausDlg(key, s, why, ok) {
  const name = leafName(key);
  modal({
    title: 'Does this look right?',
    body: `<div style="font-weight:700;margin-bottom:6px">${esc(plausLine(key, s))}</div>
      <ul class="plaus">${why.map(x => `<li>${esc(x)}</li>`).join('')}</ul>
      <div class="sub">Fix the numbers, or log it as typed.</div>`,
    foot: `<button class="btn ghost" data-close>Fix it</button><button class="btn primary" id="plOk">Log anyway</button>`,
    onOpen: bg => { $('#plOk', bg).onclick = () => { closeModal(); ok(); }; },
  });
}

/* Several sets at once, at finish or after an edit — anything ticked and then
   retyped never went past the single-set prompt. */
export function plausListDlg(flagged, verb, ok) {
  modal({
    title: 'Some sets look off',
    body: `${flagged.map(f => `<div class="card tight" style="margin-bottom:8px">
        <div style="font-weight:700">${esc(f.name)} · ${esc(f.s.w > 0 ? wt(f.s.w) + ' × ' : '')}${f.s.r} reps</div>
        <ul class="plaus" style="margin-bottom:0">${f.why.map(x => `<li>${esc(x)}</li>`).join('')}</ul>
      </div>`).join('')}
      <div class="sub">Go back and fix them, or ${esc(verb.toLowerCase())} as they are.</div>`,
    foot: `<button class="btn ghost" data-close>Go back</button><button class="btn primary" id="plOk">${esc(verb)} anyway</button>`,
    onOpen: bg => { $('#plOk', bg).onclick = () => { closeModal(); ok(); }; },
  });
}

/* ---------------- testing log ----------------
   A test is a completed session flagged `tested`, holding one 1-rep set per
   lift attempted. Log one lift or three — whatever actually got tested that
   day. Because it lands as a normal 1-rep set, bestSingleInfo picks it up as
   a true single rather than an Epley estimate, and everything downstream —
   total, DOTS, rankings, opener suggestions — follows without a second path. */
export function logTest(date, entries, notes) {
  const clean = entries.filter(e => e.leaf && e.kg > 0);
  if (!clean.length) return 0;
  S.workouts.push({
    id: uid(), date, name: clean.length === 1 ? `${shortLift(displayName(clean[0].leaf))} test` : 'Max test',
    status: 'completed', source: 'logged', tested: true, notes: notes || '',
    exercises: clean.map(e => ({
      leaf: e.leaf, legacyName: e.legacyName || displayName(e.leaf), notes: '', mods: [],
      sets: [{ w: e.kg, r: 1, rpe: null, done: true, setType: 'working' }],
    })),
    start: null, end: parseISO(date).getTime(),
    summary: { mins: 0, prs: [], volume: clean.reduce((t, e) => t + e.kg, 0) },
  });
  save(); bust();
  return clean.length;
}

export function testLog() {
  return S.workouts.filter(w => w.tested)
    .sort((a, b) => a.date < b.date ? 1 : -1);
}

/* Most recent tested single for a lift — recency beats magnitude here, because
   an opener should reflect where you are now, not the best day you ever had. */
/* Keyed on the leaf. It matched on x.name until now, which no entry has carried
   since 0.7.0 — so it always returned null and meets silently fell back to
   planned attempts, never using a tested single. */
export function latestTest(key) {
  for (const w of testLog()) {
    const e = (w.exercises || []).find(x => exKey(x) === key);
    if (e && e.sets[0] && e.sets[0].w > 0) return { kg: e.sets[0].w, date: w.date };
  }
  return null;
}

export function openerPct() { return S.settings.openerPct || 90; }

/* Suggested opener from the latest test, not from the goal third. Returns null
   when the lift hasn't been tested — better a blank than a number derived from
   a rep-max estimate, which is what the opener is meant to replace. */
function testedOpener(key) {
  const t = latestTest(key);
  if (!t) return null;
  return { kg: roundBar(t.kg * (openerPct() / 100)), from: t.kg, date: t.date };
}

/* ---------------- UI helpers ---------------- */
/* Where a completed session's numbers came from. Only a backfill is the plan's
   prescription rather than real lifting, so only it gets the EST caveat. */
export function srcChip(w) {
  if (w.source === 'backfill') return ' <span class="chip">EST</span>';
  if (w.source === 'imported') return ' <span class="chip blue">IMPORT</span>';
  return '';
}

export function last7() {
  return S.checkins.filter(c => daysBetween(c.date, today()) <= 7 && daysBetween(c.date, today()) >= 0);
}
export function avg(a) { return a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0; }
export function streak() {
  let n = 0, d = new Date();
  // allow today to be missing without breaking the streak
  if (!checkinFor(iso(d))) d.setDate(d.getDate() - 1);
  while (checkinFor(iso(d))) { n++; d.setDate(d.getDate() - 1); }
  return n;
}
// "1×5 @150, 3×5 @135" — groups consecutive identical sets
export function setSummary(e) {
  const groups = [];
  e.sets.forEach(s => {
    const last = groups[groups.length - 1];
    if (last && last.w === s.w && last.r === s.r) last.n++;
    else groups.push({ n: 1, w: s.w, r: s.r });
  });
  return groups.map(g =>
    `${g.n}×${g.r || 'AMRAP'}${g.w ? ` @ ${wt(g.w)}` : ''}`).join(', ') || '—';
}

/* Volume respects the load convention: a per-side set of 20 kg x 10 is 400 kg. */
export function totalVolume(wo) {
  return wo.exercises.reduce((a, e) => a + e.sets.filter(s => s.done && isWorking(s)).reduce((b, s) => b + setVolume(e.leaf, s), 0), 0);
}

export function goalCurrent(g) {
  if (g.type === 'lift') return bestSingleKg(g.exercise);
  if (g.type === 'bodyweight') return bodyweightKg();
  if (g.type === 'total') return priorityKeys().reduce((a, k) => a + bestSingleKg(k), 0);
  if (g.type === 'sessions') return S.workouts.filter(w => w.status === 'completed' && (!g.since || w.date >= g.since)).length;
  return g.current || 0;
}
/* What a lift goal is a goal FOR: the movement with its equipment always
   spelled out (a goal row has no picker beside it to show the default), plus
   any grip or one-arm detail, and the equipment's glyph. */
function goalLiftLine(key) {
  const leaf = keyLeaf(key);
  const eq = EQ_LABEL[leaf.equipment] || leaf.equipment || '';
  const bits = [eq, ...variantLabel(leaf).split(', ').filter(b => b && b !== eq)].filter(Boolean);
  const what = bits.length ? bits.join(', ') : '';
  return `<div class="sub goalex">${EQ_ICON[leaf.equipment] || ''}<span>${esc(displayName(leaf))}${what ? ` · ${esc(what[0].toUpperCase() + what.slice(1))}` : ''}</span></div>`;
}
export function goalRow(g) {
  const cur = goalCurrent(g);
  const start = g.startVal ?? 0;
  /* A strength goal fills to how much of the target you can already lift —
     175 of 200 is most of the way there, not 0% because that is where you
     stood when you set it. Where you started is a mark on the bar, and the
     gain since is in words. Bodyweight can run either way (a cut or a bulk),
     so it still measures from the start. */
  const fromStart = g.type === 'bodyweight';
  const pct = fromStart ? ((cur - start) / ((g.target - start) || 1)) * 100 : (cur / (g.target || 1)) * 100;
  const isCount = g.type === 'sessions';
  const f = v => isCount ? Math.round(v) : wt(v);
  const left = g.deadline ? daysBetween(today(), g.deadline) : null;
  const showStart = !fromStart && !isCount && start > 0 && start < g.target;
  const gain = showStart && cur > start ? ` · +${wt(cur - start)} since you set it` : '';
  const mark = showStart ? clamp(start / g.target * 100, 0, 100) : null;
  const b = bar(pct, fromStart ? 'blue' : '');
  return `<div class="goal" data-goal="${g.id}">
    <div class="row between" style="margin-bottom:6px">
      <div class="grow"><div style="font-weight:650;font-size:14px">${esc(g.name)}</div>
        ${g.type === 'lift' && g.exercise ? goalLiftLine(g.exercise) : ''}
        <div class="sub">${f(cur)} of ${f(g.target)}${gain}${left !== null ? ` · ${left >= 0 ? left + ' days left' : 'past deadline'}` : ''}</div></div>
      <div class="right">
        <div style="font-weight:750;font-size:15px;${pct >= 100 ? 'color:var(--green)' : ''}">${Math.round(clamp(pct, 0, 999))}%</div>
      </div>
    </div>
    ${mark != null ? b.replace('</i>', `</i><b class="mk" style="left:${mark}%" title="Where you started: ${esc(wt(start))}"></b>`) : b}
  </div>`;
}

/* ============================================================
   ANALYTICS
   ============================================================ */
export function viewAnalytics() {
  const stats = allStats();
  const q = analyticsQuery.toLowerCase();
  let list = q ? stats.filter(s => s.name.toLowerCase().includes(q)) : stats;
  list = [...list].sort((a, b) => {
    if (analyticsSort === 'sessions') return b.sessions - a.sessions;
    if (analyticsSort === 'pr') return b.best.e1 - a.best.e1;
    if (analyticsSort === 'progress') return b.pct - a.pct;
    if (analyticsSort === 'recent') return a.lastDate < b.lastDate ? 1 : -1;
    return 0;
  });

  const totalSessions = S.workouts.filter(w => w.status === 'completed' && w.kind !== 'mobility').length;
  const totalVol = S.workouts.filter(w => w.status === 'completed').reduce((a, w) => a + totalVolume(w), 0);
  const totalPRs = S.workouts.filter(w => w.status === 'completed').reduce((a, w) => a + prsFor(w).length, 0);

  return `
  <h1>Stats</h1>
  <div class="sub" style="margin-bottom:14px">Every exercise you've logged, ranked.</div>

  <div class="seg" id="anTabs" style="margin-bottom:13px">
    ${[['exercises', 'Exercises'], ['rankings', 'Rankings'], ['muscles', 'Muscles']]
      .map(([k, l]) => `<button data-antab="${k}" class="${analyticsTab === k ? 'on' : ''}">${l}</button>`).join('')}
  </div>

  ${analyticsTab === 'exercises' ? '' : (() => {
      const ranks = allRanks(), ms = muscleScores(), bw = bodyweightKg();
      const recOnly = analyticsTab === 'muscles' ? viewMuscleMap() + viewWeeklySets() : '';   // recovery and weekly sets need no ranks (D7, 01)
      if (!bw) return `${recOnly}<div class="card"><div class="eyebrow" style="margin-bottom:6px">Rankings</div>
      <div class="sub">Log a check-in with your bodyweight — every standard is a multiple of it.</div></div>`;
      if (!ranks.length) return `${recOnly}<div class="card"><div class="empty">Nothing ranked yet — rankings cover the lifts with a strength standard.</div></div>`;
      const bar = (score, color) => `<div class="bar"><i style="width:${Math.max(2, score).toFixed(1)}%;background:${color}"></i></div>`;
      if (analyticsTab === 'rankings') return `
  <div class="card flush" style="margin-bottom:13px">
    <div class="row between" style="padding:11px 13px 8px">
      <div class="eyebrow">Rankings · per lift</div>
      <div class="sub" style="font-size:11px">at ${wt(bw, 1)} bw</div>
    </div>
    ${ranks.slice(0, 12).map(r => `
      <div class="rank-row" data-exdetail="${esc(r.key)}">
        <div class="grow">
          <div class="n">${r.leaf ? keyNameHtml(r.key) : esc(r.name)}${r.estOnly ? ' <span class="chip">EST</span>' : ''}</div>
          <div class="m"><span class="tierlab" style="color:${r.color}">${r.tierName}</span>
            · ${wt(r.e1)} e1RM · ${r.ratio.toFixed(2)}× bw${r.nextName ? ` · ${wt(r.toNext)} to ${r.nextName}` : ''} ${why('rank', r.key)}</div>
          ${bar(r.score, r.color)}
        </div>
        <div class="rank-sc" style="color:${r.color}">${Math.round(r.score)}</div>
      </div>`).join('')}
    <div class="sub" style="padding:9px 13px 11px;border-top:1px solid var(--line)">
      Scored against general able-bodied strength tables, 20 points per tier. A reference point, not a verdict — your leverages aren't what those tables assume.
    </div>
  </div>`;
      return `
  ${viewMuscleMap()}
  ${viewWeeklySets()}
  ${ms.length ? `
  <div class="card flush" style="margin-bottom:13px">
    <div class="eyebrow" style="padding:11px 13px 8px">Rankings · muscle groups</div>
    ${ms.map(m => {
        const i = clamp(Math.floor(m.score / 20), 0, 4);
        const col = m.score < 20 ? 'var(--dim)' : TIER_COLOR[i];
        return `<div class="rank-row">
        <div class="grow">
          <div class="n">${esc(m.name)}</div>
          <div class="m">${m.lifts} ranked lift${m.lifts === 1 ? '' : 's'}</div>
          ${bar(m.score, col)}
        </div>
        <div class="rank-sc" style="color:${col}">${Math.round(m.score)}</div>
      </div>`;
      }).join('')}
    <div class="sub" style="padding:9px 13px 11px;border-top:1px solid var(--line)">
      Share-weighted average of the lifts that train each muscle. Weakest at the bottom — that's the useful end.
    </div>
  </div>` : ''}`;
    })()}

  ${analyticsTab !== 'exercises' ? '' : `
  <div class="stats grid3" style="margin-bottom:13px">
    <div class="stat"><div class="k">Sessions</div><div class="v">${totalSessions}</div></div>
    <div class="stat"><div class="k">Volume</div><div class="v">${w(totalVol, 0)}</div><div class="d">all time</div></div>
    <div class="stat"><div class="k">PRs</div><div class="v">${totalPRs}</div><div class="d">all time</div></div>
  </div>

  ${mainLiftChart()}`}

  ${analyticsTab !== 'exercises' ? '' : stats.length ? `
  <input id="anQ" aria-label="Search exercises" placeholder="Search exercises…" value="${esc(analyticsQuery)}" autocomplete="off" style="margin-bottom:10px">
  <div class="seg" style="margin-bottom:13px">
    ${[['sessions', 'Sessions'], ['pr', 'PR'], ['progress', 'Progress'], ['recent', 'Recent']]
        .map(([k, l]) => `<button data-sort="${k}" class="${analyticsSort === k ? 'on' : ''}">${l}</button>`).join('')}
  </div>
  <div class="card flush">
    ${list.map(s => {
          const t = s.pct > 1 ? 'up' : s.pct < -1 ? 'down' : 'flat';
          return `<div class="ex-row" data-exdetail="${esc(s.key)}">
        <div class="grow">
          <div class="n">${s.leaf ? keyNameHtml(s.key) : esc(s.name)}</div>
          <div class="m">${s.sessions} session${s.sessions === 1 ? '' : 's'} · ${s.totalSets} sets · last ${relDay(s.lastDate)}</div>
        </div>
        <div class="pr">
          ${wt(s.bestW.w)} × ${s.bestW.r}
          <small>e1RM ${wt(s.best.e1)}</small>
        </div>
        <div class="trend ${t}" style="width:52px;text-align:right">${s.pct > 0 ? '▲' : s.pct < 0 ? '▼' : '—'} ${Math.abs(Math.round(s.pct))}%</div>
      </div>`;
        }).join('') || `<div class="empty">No exercise matches “${esc(analyticsQuery)}”.</div>`}
  </div>` : `<div class="card"><div class="empty"><span class="big">◫</span>No completed workouts yet.<br>Log a session and this fills up.</div>
      <div class="row" style="margin-top:10px"><button class="btn sm primary grow" data-go="workout">Go to Train</button></div></div>`}
  `;
}

/* The headline chart (roadmap B5): e1RM per session for the main lifts —
   your priority lifts, or else the three most-trained heavy barbell lifts.
   The last twelve months, so a long history doesn't flatten the recent line. */
export function mainLiftKeys() {
  const pk = priorityKeys().filter(k => statsFor(k));
  if (pk.length) return pk.slice(0, 5);
  return allStats().filter(s => s.leaf && isMainLift({ leaf: s.leaf })).slice(0, 3).map(s => s.key);
}
function mainLiftChart() {
  const keys = mainLiftKeys();
  if (!keys.length) return '';
  const d = new Date(); d.setFullYear(d.getFullYear() - 1);
  const since = iso(d);
  const series = keys.map((k, i) => {
    const st = statsFor(k);
    const recent = st.series.filter(p => p.date >= since);
    return { label: leafName(k), color: SERIES_COLORS[i % SERIES_COLORS.length],
      points: (recent.length >= 2 ? recent : st.series).map(p => ({ date: p.date, v: dw(p.e1) })), st };
  });
  return `<div class="card" style="margin-bottom:13px">
    <div class="row between" style="margin-bottom:6px"><div class="eyebrow">e1RM trend · main lifts</div>
      <div class="sub" style="font-size:11px">${priorityKeys().some(k => keys.includes(k)) ? 'your priority lifts' : 'most-trained heavy lifts'}</div></div>
    ${chartMulti(series, { fmt: v => nice(Math.round(v)) })}
    <div class="row wrap" style="gap:6px;margin-top:8px">${series.map(s => {
      const pct = s.st.pct;
      return `<button class="chip" data-exdetail="${esc(keys[series.indexOf(s)])}" style="border-color:${s.color}">${esc(s.label)} ${wt(s.st.best.e1)}
        <span style="color:${pct > 1 ? 'var(--green)' : pct < -1 ? 'var(--red)' : 'var(--dim)'}">${pct > 1 ? '▲' : pct < -1 ? '▼' : '—'}${Math.abs(Math.round(pct))}%</span></button>`;
    }).join('')}</div>
  </div>`;
}

let detailMetric = 'e1';
/* Every leaf of this movement that has been logged, plus the primary — so the
   page always offers the canonical variant even before it has been done. */
export function movementVariants(movementId) {
  const keys = new Set();
  S.workouts.filter(w => w.status === 'completed').forEach(wo => wo.exercises.forEach(e => {
    // holds, caps, carries and races keep their own records and have no e1RM, so they're not a variant row here
    if (e.leaf && e.leaf.movement === movementId && inRepsPool(e)) keys.add(exKey(e));
  }));
  const m = movementById(movementId);
  if (m) keys.add(leafKey(completeLeaf(m, null)));
  return [...keys].map(k => ({ key: k, leaf: keyLeaf(k), name: displayName(keyLeaf(k)), stats: statsFor(k) }))
    .sort((a, b) => (b.stats ? b.stats.sessions : 0) - (a.stats ? a.stats.sessions : 0));
}
/* The primary variant is the movement at its defaults — Aaron's IPF squat is
   Back Squat / barbell / bilateral, not "best squat variant". */
export function primaryVariantKey(movementId) {
  const m = movementById(movementId);
  return m ? leafKey(completeLeaf(m, null)) : null;
}
